<?php
require_once __DIR__ . '/db.php';
if (session_status() !== PHP_SESSION_ACTIVE) { session_start(); }
require_login('Medewerker');
$pdo=database(); $error=''; $message='';
if ($_SERVER['REQUEST_METHOD']==='POST') { $title=trim($_POST['title']??''); $author=trim($_POST['author']??''); $category=trim($_POST['category']??''); $year=filter_var($_POST['year']??'',FILTER_VALIDATE_INT,['options'=>['min_range'=>1000,'max_range'=>2100]]); if($title===''||$author===''||$category===''||$year===false){$error='Vul titel, auteur, categorie en een geldig jaar in.';}else{$query=$pdo->prepare('INSERT INTO books (title,author,category,year,status,description) VALUES (?,?,?,?,?,?)');$query->execute([$title,$author,$category,$year,'Beschikbaar','Nieuw toegevoegd aan de collectie.']);$message='Het boek is toegevoegd.';}}
$books=$pdo->query('SELECT id,title,author,category FROM books ORDER BY title')->fetchAll(); $memberSearch=trim($_GET['member_q']??''); $query=$pdo->prepare('SELECT id,name,email,rol AS role FROM `user` WHERE rol=? AND name LIKE ? ORDER BY name'); $query->execute(['Lid','%'.$memberSearch.'%']); $members=$query->fetchAll(); $loans=$pdo->query('SELECT u.name,books.title FROM loans JOIN `user` AS u ON u.id=loans.user_id JOIN books ON books.id=loans.book_id WHERE loans.returned_at IS NULL ORDER BY u.name')->fetchAll(); $title='Beheer'; require __DIR__ . '/header.php';
?><section style="padding:55px 0 70px"><span class="eyebrow">Medewerkersomgeving</span><h1>Collectie beheren.</h1><p>Boeken, leningen en leden op één plek.</p><div style="display:grid;grid-template-columns:1.5fr 1fr;gap:24px;margin:30px 0 60px"><div><h2>Alle boeken</h2><table style="width:100%;border-collapse:collapse;background:var(--card);font:14px Arial"><tr><th style="text-align:left;padding:14px">Boek</th><th style="text-align:left;padding:14px">Categorie</th></tr><?php foreach($books as $book): ?><tr><td style="padding:14px;border-top:1px solid var(--line)"><strong><?= e($book['title']) ?></strong><br><span class="meta"><?= e($book['author']) ?></span></td><td style="padding:14px;border-top:1px solid var(--line)"><?= e($book['category']) ?></td></tr><?php endforeach; ?></table></div><form method="post" class="panel"><h2>Boek toevoegen</h2><div class="field"><label>Titel</label><input name="title" required></div><div class="field"><label>Auteur</label><input name="author" required></div><div class="field"><label>Categorie</label><input name="category" required></div><div class="field"><label>Jaar</label><input name="year" type="number" min="1000" max="2100" required></div><button type="submit">Toevoegen</button></form></div><h2>Actieve leningen</h2><?php if($loans): ?><p><?php foreach($loans as $loan): ?><?= e($loan['name']) ?> → <?= e($loan['title']) ?><br><?php endforeach; ?></p><?php else: ?><p class="meta">Geen actieve leningen.</p><?php endif; ?><h2 style="margin-top:40px">Leden zoeken</h2><form method="get" style="display:flex;gap:10px;margin:14px 0"><input name="member_q" placeholder="Zoek op naam..." value="<?= e($memberSearch) ?>"><button type="submit">Zoeken</button></form><table style="width:100%;border-collapse:collapse;background:var(--card);font:14px Arial"><tr><th style="text-align:left;padding:14px">Naam</th><th style="text-align:left;padding:14px">E-mail</th></tr><?php foreach($members as $member): ?><tr><td style="padding:14px;border-top:1px solid var(--line)"><?= e($member['name']) ?></td><td style="padding:14px;border-top:1px solid var(--line)"><?= e($member['email']) ?></td></tr><?php endforeach; ?></table></section><?php require __DIR__ . '/footer.php'; ?>
